from pathlib import Path
import numpy as np
# Add replay diagnostics without extra calls to the environment success checker.
p='''import os, json, sys
os.environ.setdefault('MUJOCO_GL', 'egl')
import numpy as np, casa_tool
s = casa_tool.Session('/app/instance.npz')
a = np.load(sys.argv[1], allow_pickle=False)['actions']
r = s.replay(a)
bid = s.env.obj_body_id
p = {k:s.data.xpos[bid[k]].copy() for k in ['knife','meat','receptacle']}
eef = s.data.site_xpos[s.env.robots[0].eef_site_id['right']].copy()
r['board_radius'] = float(s.env.objects['receptacle'].horizontal_radius)
r['horizontal_distance'] = {k:float(np.linalg.norm((p[k]-p['receptacle'])[:2])) for k in ['knife','meat']}
r['hand_distance'] = {k:float(np.linalg.norm(eef-p[k])) for k in ['knife','receptacle']}
r['object_positions'] = {k:v.tolist() for k,v in p.items()}
r['max_joint_command_increment'] = float(np.abs(np.diff(a[:,:7],axis=0)).max())
for _ in range(200):
    s.step(s.hold_targets())
r['success_after_extra_10_seconds'] = bool(s.check()['success'])
print(json.dumps(r), flush=True)
